// Fixpt's `exp`, each node with where it starts (its `a`): a variable, the
// literals, a lambda of its parameters' names, an application, `if`,
// `let`, `letrec`, `begin`, a product of its fields, an `extract` of the
// field the checker found (`extract-index`), a sum, a `tagcase`. Type
// abstractions and ascriptions compile to nothing, so are not kept.
pub enum Cx {
    XVar(Str, i64),
    XInt(Int, i64),
    XBool(bool, i64),
    XStr(Str, i64),
    XChar(char, i64),
    XSym(Str, i64),
    XUnit(i64),
    XLambda(Strings, &'static Cx, i64),
    XApp(&'static Cx, List<&'static Cx>, i64),
    XIf(&'static Cx, &'static Cx, &'static Cx, i64),
    XLet(List<&'static Cbind>, &'static Cx, i64),
    XLetrec(List<&'static Cbind>, &'static Cx, i64),
    XBegin(List<&'static Cx>, i64),
    XProduct(List<&'static Cbind>, i64),
    XExtract(&'static Cx, i64, i64),
    XSum(Str, &'static Cx, i64),
    XTagcase(&'static Cx, List<&'static Carm>, List<&'static Cbind>, i64),
}

pub fn x_var(f0: Str, f1: i64) -> &'static Cx {
    kayak_rt::heap_alloc(Cx::XVar(f0, f1))
}

pub fn x_int(f0: Int, f1: i64) -> &'static Cx {
    kayak_rt::heap_alloc(Cx::XInt(f0, f1))
}

